use super::*;use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation};use semio_framework_value::retained_clone::RetainedCloneGrant;
fn clock()->Option<u64>{Some(1)}fn grant(items:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:items,maximum_copy_bytes:32768,maximum_capacity_bytes:16777216,maximum_release_bytes:1048576,maximum_depth:4096}}
#[test]fn neutral_sparse_ordinals_resume_invalidate_and_return(){let request=super::super::tests::request(4);let mut caller=OriginalJobFixtureCaller::admit(OperationId(request.identity.operation),Generation(request.identity.generation),grant(1<<20),clock,u64::MAX,1<<20);let fixture=semio_framework_pack_json::parse(include_str!("🔣️.json"),semio_framework_pack_json::JsonMemberPolicy::Reject).unwrap();let mut index=SourceVertexIndex::new(request.identity,50000);for row in fixture["cases"].as_array().unwrap(){let source=row["index"].as_u64().unwrap()as u32;let vertex=row["vertex"].as_u64().unwrap()as u32;let generation=row["generation"].as_u64().unwrap()as u32;for _ in 0..16{if caller.turn(grant(1),|cx|Ok(index.put(source,vertex,generation,&mut PreparationTurn{identity:&request.identity,cx},0,usize::MAX).unwrap())).unwrap(){break}}assert_eq!(index.get(source,generation).unwrap(),vertex);assert_eq!(index.get(source,generation+1).unwrap(),0);}assert!(index.allocated_bytes()<=50000);index.begin_close();for _ in 0..100{if index.terminal_is_empty(){break}caller.turn(grant(1),|cx|cx.with_original_retirement(|cx|{index.close(&mut PreparationTurn{identity:&request.identity,cx}).unwrap();Ok(())})).unwrap();}assert!(index.terminal_is_empty());caller.retire(grant(1<<20));}
